public class FitnessFunction_encode_TriageGen1Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testEncode_BoundariesIsNull() {
        // Arrange
        org.apache.commons.math3.optimization.direct.CMAESOptimizer.FitnessFunction fitnessFunction = 
            new org.apache.commons.math3.optimization.direct.CMAESOptimizer.FitnessFunction();
        double[] x = {1.0, 2.0, 3.0};

        // Act
        // Since boundaries is null by default via constructor
        double[] result = fitnessFunction.encode(x);

        // Assert
        // The code returns the same reference when boundaries is null
        assertSame(x, result);
    }

    @Test
    public void testEncode_NormalScaling() {
        // Arrange
        org.apache.commons.math3.optimization.direct.CMAESOptimizer.FitnessFunction fitnessFunction = 
            new org.apache.commons.math3.optimization.direct.CMAESOptimizer.FitnessFunction();

        // We need to set boundaries. Since boundaries is likely a private field, 
        // in a real scenario we would use a setter or reflect it. 
        // However, based on the provided code snippet, we assume we can influence it.
        // For the sake of this test, we assume the class allows setting boundaries 
        // or we use reflection to simulate the state.

        double[][] boundaries = {
            {0.0, 10.0, -5.0}, // Lower bounds
            {10.0, 20.0, 5.0}  // Upper bounds
        };

        try {
            java.lang.reflect.Field field = org.apache.commons.math3.optimization.direct.CMAESOptimizer.FitnessFunction.class.getDeclaredField("boundaries");
            field.setAccessible(true);
            field.set(fitnessFunction, boundaries);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        double[] x = {5.0, 15.0, 0.0};
        // Expected:
        // (5.0 - 0.0) / (10.0 - 0.0) = 0.5
        // (15.0 - 10.0) / (20.0 - 10.0) = 0.5
        // (0.0 - (-5.0)) / (5.0 - (-5.0)) = 5.0 / 10.0 = 0.5
        double[] expected = {0.5, 0.5, 0.5};

        // Act
        double[] result = fitnessFunction.encode(x);

        // Assert
        assertArrayEquals(expected, result, DELTA);
    }

    @Test
    public void testEncode_ZeroAndNegativeValues() {
        // Arrange
        org.apache.commons.math3.optimization.direct.CMAESOptimizer.FitnessFunction fitnessFunction = 
            new org.apache.commons.math3.optimization.direct.CMAESOptimizer.FitnessFunction();

        double[][] boundaries = {
            {-10.0, -10.0},
            {10.0, 10.0}
        };

        try {
            java.lang.reflect.Field field = org.apache.commons.math3.optimization.direct.CMAESOptimizer.FitnessFunction.class.getDeclaredField("boundaries");
            field.setAccessible(true);
            field.set(fitnessFunction, boundaries);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        double[] x = {-10.0, 10.0};
        // Expected:
        // (-10.0 - (-10.0)) / 20.0 = 0.0
        // (10.0 - (-10.0)) / 20.0 = 1.0
        double[] expected = {0.0, 1.0};

        // Act
        double[] result = fitnessFunction.encode(x);

        // Assert
        assertArrayEquals(expected, result, DELTA);
    }

    @Test
    public void testEncode_EmptyArray() {
        // Arrange
        org.apache.commons.math3.optimization.direct.CMAESOptimizer.FitnessFunction fitnessFunction = 
            new org.apache.commons.math3.optimization.direct.CMAESOptimizer.FitnessFunction();

        double[][] boundaries = {
            {},
            {}
        };

        try {
            java.lang.reflect.Field field = org.apache.commons.math3.optimization.direct.CMAESOptimizer.FitnessFunction.class.getDeclaredField("boundaries");
            field.setAccessible(true);
            field.set(fitnessFunction, boundaries);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }

        double[] x = {};

        // Act
        double[] result = fitnessFunction.encode(x);

        // Assert
        assertEquals(0, result.length);
    }
